window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-70a8b91549ce8e7c"]={"versions": [{"id": "FIG-70a8b91549ce8e7c", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung der Kopplung zwischen dem AUTOSAR ECU Resource Template und dem System Constraint Template (Topologie). Es definiert die strukturellen Typ-Instanz-Beziehungen zwischen Hardware-Ressourcenbeschreibungen auf Typ-Ebene und deren topologischen Ausprägungen im System-Kontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Klassen, Stereotypen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Klassen &amp; Spezialisierungen/Interfaces:</strong>\n<ul class=\"fig-list\"><li><code>Topology::ECUInstance</code>: Spezialisiert bzw. realisiert <code>ExistenceDependsOnProperty</code>, <code>Namespace</code>, <code>PropertyContainer</code> und <code>PropertyEvaluator</code>.\n</li><li><code>Topology::ECUCommunicationPortInstance</code>: Spezialisiert bzw. realisiert <code>ExistenceDependsOnProperty</code> und <code>Identifiable</code>.\n</li><li><code>ECUResourceTemplate::ECU</code>: Spezialisiert <code>HWElementContainer</code>.\n</li><li><code>Peripherals::ECUCommunicationPort</code>: Spezialisiert das abstrakte/übergeordnete Element <code>Peripherals::CommunicationHWPort</code> (welches wiederum <code>PeripheralHWPort</code> realisiert/spezialisiert).\n</li></ul>\n</li><li><strong>Assoziationen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition:</strong> <code>Topology::ECUInstance</code> aggregiert per Komposition (<code>+portInstances</code>, Kardinalität <code>*</code>) Instanzen von <code>Topology::ECUCommunicationPortInstance</code>.\n</li><li><strong>Typisierungs-Assoziationen (<code>«isOfType»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Topology::ECUInstance</code> referenziert über die Assoziation <code>+ecu</code> mit Multiplizität <code>1</code> (ausgehend von <code>*</code>) die Typdefinition <code>ECUResourceTemplate::ECU</code>.\n</li><li><code>Topology::ECUCommunicationPortInstance</code> referenziert über die Assoziation <code>+port</code> mit Multiplizität <code>1</code> (ausgehend von <code>*</code>) die Port-Typdefinition <code>Peripherals::ECUCommunicationPort</code>.\n</li></ul>\n</li><li><strong>Abhängigkeiten (gestrichelte Pfeile):</strong>\n<ul class=\"fig-list\"><li>Abhängigkeitsbeziehung von <code>ECUResourceTemplate::ECU</code> zu <code>Peripherals::ECUCommunicationPort</code>.\n</li><li>Abhängigkeitsbeziehung von <code>ECUResourceTemplate::ECU</code> zu <code>Peripherals::CommunicationHWPort</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Sequenz- oder Verhaltensdiagrammelemente. Es definiert Deklarations- und Referenzierungsregeln für die statische Systemkonfiguration, bei der Topologie-Instanzen auf Ressourcentypen abgebildet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Modellierungsregeln für AUTOSAR-Systembeschreibungen:</p>\n<ul class=\"fig-list\"><li>Jede <code>Topology::ECUInstance</code> muss exakt einer Typdefinition <code>ECUResourceTemplate::ECU</code> zugeordnet sein (<code>1</code>).\n</li><li>Jeder <code>Topology::ECUCommunicationPortInstance</code> innerhalb einer ECU-Instanz muss exakt einem <code>Peripherals::ECUCommunicationPort</code> zugeordnet sein (<code>1</code>).\n</li><li>Eine ECU-Instanz kann null bis beliebig viele (<code>*</code>) Kommunikations-Port-Instanzen (<code>+portInstances</code>) per Lebenszyklus-gebundener Komposition besitzen.\n</li><li>Beide Instanzklassen unterliegen den Mechanismen von <code>ExistenceDependsOnProperty</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-476ef973b889d130", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung der Kopplung zwischen dem AUTOSAR ECU Resource Template und dem System Constraint Template (Topologie). Es definiert die strukturellen Typ-Instanz-Beziehungen zwischen Hardware-Ressourcenbeschreibungen auf Typ-Ebene und deren topologischen Ausprägungen im System-Kontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Klassen, Stereotypen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Klassen &amp; Spezialisierungen/Interfaces:</strong>\n<ul class=\"fig-list\"><li><code>Topology::ECUInstance</code>: Spezialisiert bzw. realisiert <code>ExistenceDependsOnProperty</code>, <code>Namespace</code>, <code>PropertyContainer</code> und <code>PropertyEvaluator</code>.\n</li><li><code>Topology::ECUCommunicationPortInstance</code>: Spezialisiert bzw. realisiert <code>ExistenceDependsOnProperty</code> und <code>Identifiable</code>.\n</li><li><code>ECUResourceTemplate::ECU</code>: Spezialisiert <code>HWElementContainer</code>.\n</li><li><code>Peripherals::ECUCommunicationPort</code>: Spezialisiert das abstrakte/übergeordnete Element <code>Peripherals::CommunicationHWPort</code> (welches wiederum <code>PeripheralHWPort</code> realisiert/spezialisiert).\n</li></ul>\n</li><li><strong>Assoziationen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition:</strong> <code>Topology::ECUInstance</code> aggregiert per Komposition (<code>+portInstances</code>, Kardinalität <code>*</code>) Instanzen von <code>Topology::ECUCommunicationPortInstance</code>.\n</li><li><strong>Typisierungs-Assoziationen (<code>«isOfType»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Topology::ECUInstance</code> referenziert über die Assoziation <code>+ecu</code> mit Multiplizität <code>1</code> (ausgehend von <code>*</code>) die Typdefinition <code>ECUResourceTemplate::ECU</code>.\n</li><li><code>Topology::ECUCommunicationPortInstance</code> referenziert über die Assoziation <code>+port</code> mit Multiplizität <code>1</code> (ausgehend von <code>*</code>) die Port-Typdefinition <code>Peripherals::ECUCommunicationPort</code>.\n</li></ul>\n</li><li><strong>Abhängigkeiten (gestrichelte Pfeile):</strong>\n<ul class=\"fig-list\"><li>Abhängigkeitsbeziehung von <code>ECUResourceTemplate::ECU</code> zu <code>Peripherals::ECUCommunicationPort</code>.\n</li><li>Abhängigkeitsbeziehung von <code>ECUResourceTemplate::ECU</code> zu <code>Peripherals::CommunicationHWPort</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Sequenz- oder Verhaltensdiagrammelemente. Es definiert Deklarations- und Referenzierungsregeln für die statische Systemkonfiguration, bei der Topologie-Instanzen auf Ressourcentypen abgebildet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Modellierungsregeln für AUTOSAR-Systembeschreibungen:</p>\n<ul class=\"fig-list\"><li>Jede <code>Topology::ECUInstance</code> muss exakt einer Typdefinition <code>ECUResourceTemplate::ECU</code> zugeordnet sein (<code>1</code>).\n</li><li>Jeder <code>Topology::ECUCommunicationPortInstance</code> innerhalb einer ECU-Instanz muss exakt einem <code>Peripherals::ECUCommunicationPort</code> zugeordnet sein (<code>1</code>).\n</li><li>Eine ECU-Instanz kann null bis beliebig viele (<code>*</code>) Kommunikations-Port-Instanzen (<code>+portInstances</code>) per Lebenszyklus-gebundener Komposition besitzen.\n</li><li>Beide Instanzklassen unterliegen den Mechanismen von <code>ExistenceDependsOnProperty</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-70a8b91549ce8e7c", "to": "FIG-476ef973b889d130", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
